From 23a8f88d88a7aa4bb73bf5380b04682849ba93cc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:20:30 +0100
Subject: [PATCH] applets/taskmanager: show a separator between pinned and
 other apps

The Icons-Only Task Manager gave no hint of where pinned apps end, so it
was unclear why a running app can't be dragged in among them. Leave a
small gap after the last pinned app and draw a thin line in it.

BUG: 459648
---
 applets/taskmanager/qml/Task.qml |  2 ++
 applets/taskmanager/qml/main.qml | 61 ++++++++++++++++++++++++++++++--
 2 files changed, 61 insertions(+), 2 deletions(-)

diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..65e4af1f10 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -46,6 +46,8 @@ PlasmaCore.ToolTipArea {
         ? -1
         : ((model.IsLauncher && !tasksRoot.iconsOnly) ? tasksRoot.height / taskList.rows : TaskManagerApplet.LayoutMetrics.preferredMaxWidth())
     Layout.maximumHeight: tasksRoot.vertical ? TaskManagerApplet.LayoutMetrics.preferredMaxHeight() : -1
+    Layout.rightMargin: !inPopup && !tasksRoot.vertical && index === tasksRoot.firstUnpinnedIndex - 1 ? Kirigami.Units.largeSpacing : 0
+    Layout.bottomMargin: !inPopup && tasksRoot.vertical && index === tasksRoot.firstUnpinnedIndex - 1 ? Kirigami.Units.largeSpacing : 0

     required property var model
     required property int index
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..16d0e1b13c 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -41,6 +41,27 @@ PlasmoidItem {

     property alias taskList: taskList

+    // Index of the first task that comes after the pinned apps, or -1 if there is no such boundary
+    readonly property int firstUnpinnedIndex: {
+        if (!tasks.iconsOnly || !tasksModel.separateLaunchers) {
+            return -1;
+        }
+        void tasksModel.launcherList;
+        let i = 0;
+        for (; i < taskRepeater.count; ++i) {
+            const item = taskRepeater.itemAt(i) as Task;
+            if (!item?.model || item.index !== i) {
+                return -1;
+            }
+            const pinned = item.model.IsLauncher
+                || (tasksModel.launchInPlace && tasks.hasLauncher(item.model.LauncherUrlWithoutIcon));
+            if (!pinned) {
+                break;
+            }
+        }
+        return i > 0 && i < taskRepeater.count ? i : -1;
+    }
+
     preferredRepresentation: fullRepresentation

     Plasmoid.constraintHints: Plasmoid.CanFillArea
@@ -482,7 +503,7 @@ PlasmoidItem {
                             if (!isFinite(child.Layout.maximumWidth)) {
                                 return accumulator;
                             }
-                            return accumulator + child.Layout.maximumWidth
+                            return accumulator + child.Layout.maximumWidth + child.Layout.leftMargin + child.Layout.rightMargin
                         }, 0);
                     return Math.round(totalMaxWidth / widthOccupation);
                 }
@@ -491,7 +512,7 @@ PlasmoidItem {
                             if (!isFinite(child.Layout.maximumHeight)) {
                                 return accumulator;
                             }
-                            return accumulator + child.Layout.maximumHeight
+                            return accumulator + child.Layout.maximumHeight + child.Layout.topMargin + child.Layout.bottomMargin
                         }, 0);
                     return Math.round(totalMaxHeight / heightOccupation);
                 }
@@ -537,6 +558,42 @@ PlasmoidItem {
                     }
                 }
             }
+
+            KSvg.SvgItem {
+                id: pinnedSeparator
+
+                readonly property Task before: tasks.firstUnpinnedIndex > 0 ? taskRepeater.itemAt(tasks.firstUnpinnedIndex - 1) as Task : null
+                readonly property Task after: tasks.firstUnpinnedIndex > 0 ? taskRepeater.itemAt(tasks.firstUnpinnedIndex) as Task : null
+
+                visible: before !== null && after !== null && !tasks.shouldShrinkToZero
+                    && (tasks.vertical ? Math.abs(before.x - after.x) < 1 : Math.abs(before.y - after.y) < 1)
+
+                x: {
+                    if (!visible) {
+                        return 0;
+                    }
+                    if (tasks.vertical) {
+                        return taskList.x + before.x + Math.round((before.width - width) / 2);
+                    }
+                    const edge = before.x < after.x ? (before.x + before.width + after.x) / 2 : (after.x + after.width + before.x) / 2;
+                    return taskList.x + Math.round(edge - width / 2);
+                }
+                y: {
+                    if (!visible) {
+                        return 0;
+                    }
+                    if (!tasks.vertical) {
+                        return taskList.y + before.y + Math.round((before.height - height) / 2);
+                    }
+                    const edge = before.y < after.y ? (before.y + before.height + after.y) / 2 : (after.y + after.height + before.y) / 2;
+                    return taskList.y + Math.round(edge - height / 2);
+                }
+                width: tasks.vertical ? Math.round((before?.width ?? 0) / 2) : 1
+                height: tasks.vertical ? 1 : Math.round((before?.height ?? 0) / 2)
+
+                imagePath: "widgets/line"
+                elementId: tasks.vertical ? "horizontal-line" : "vertical-line"
+            }
         }
     }

-- 
